import fs from 'node:fs';
const envelope = JSON.parse(fs.readFileSync(0, 'utf8'));
const raw = envelope.input.sequence;
if (typeof raw !== 'string') throw new Error('sequence must be text');
const sequence = raw.split(/\r?\n/).filter(line => !line.trimStart().startsWith('>')).join('').replace(/\s/g, '').toUpperCase().replace(/U/g, 'T');
if (!/^[ACGT]+$/.test(sequence)) throw new Error('unsupported or empty sequence');
const baseCounts = { A: 0, C: 0, G: 0, T: 0 };
for (const base of sequence) baseCounts[base]++;
const gcCount = baseCounts.G + baseCounts.C;
process.stdout.write(JSON.stringify({ length: sequence.length, gcFraction: gcCount / sequence.length, baseCounts }));

